{{ config(materialized='incremental', incremental_strategy='merge',
          file_format='iceberg', unique_key='order_id') }}
select o.order_id, o.customer_id as customer_key,
       cast(o.created_at as date) as order_date, o.status, o._loaded_at,
       o.total_amount - coalesce(r.refunded, 0) as net_amount,
       row_number() over (partition by o.customer_id
                          order by o.created_at, o.order_id) as customer_order_seq
from {{ ref('stg_orders') }} o
left join {{ ref('int_refunds') }} r using (order_id)
{% if is_incremental() %}
where o.customer_id in (select customer_id from {{ ref('stg_orders') }}
                        where _loaded_at > (select max(_loaded_at) from {{ this }}))
{% endif %}

semantic_models:
  - name: orders
    model: ref('fct_orders')
    defaults: {agg_time_dimension: order_date}
    entities:
      - {name: order, type: primary, expr: order_id}
      - {name: customer, type: foreign, expr: customer_key}
    dimensions:
      - {name: order_date, type: time, type_params: {time_granularity: day}}
    measures:
      - {name: net_revenue, agg: sum, expr: net_amount}
      - {name: orders_n, agg: sum, expr: "1"}
      - {name: buyers_n, agg: count_distinct, expr: customer_key}
      - name: repeat_buyers_n
        agg: count_distinct
        expr: "case when customer_order_seq > 1 then customer_key end"
metrics:
  - {name: revenue, type: simple, type_params: {measure: net_revenue}}
  - {name: orders, type: simple, type_params: {measure: orders_n}}
  - {name: buyers, type: simple, type_params: {measure: buyers_n}}
  - {name: repeat_buyers, type: simple, type_params: {measure: repeat_buyers_n}}
  - {name: aov, type: ratio, type_params: {numerator: revenue, denominator: orders}}
  - {name: repeat_rate, type: ratio,
     type_params: {numerator: repeat_buyers, denominator: buyers}}

CALL lake.system.rewrite_data_files(table => 'silver.orders',
  options => map('target-file-size-bytes', '268435456'));
CALL lake.system.rewrite_position_delete_files(table => 'silver.orders');
CALL lake.system.expire_snapshots(table => 'silver.orders',
  older_than => TIMESTAMP '2026-11-10 00:00:00', retain_last => 50);
CALL lake.system.remove_orphan_files(table => 'silver.orders',
  older_than => TIMESTAMP '2026-11-14 00:00:00');
